def decode_shift(s: str) -> str:
    def shift_char(c: str, n: int) -> str:
        if 'a' <= c <= 'z':
            return chr((ord(c) - ord('a') + n) % 26 + ord('a'))
        return c

    # Detection heuristic: if any character shifted by -5 results in all lowercase letters,
    # assume input is encoded and decode by shifting -5,
    # else encode by shifting +5.
    # However, since input can contain non-letters, we check if shifting -5 keeps letters in 'a'-'z'.
    # We'll count how many lowercase letters become lowercase letters after shifting -5.
    # If most lowercase letters remain lowercase after shifting -5, assume encoded input.
    # Else assume decoded input.

    lowercase_letters = [c for c in s if 'a' <= c <= 'z']
    if not lowercase_letters:
        # No lowercase letters, toggle by +5 (encode) as default
        shift = 5
    else:
        shifted_minus_5 = [shift_char(c, -5) for c in lowercase_letters]
        # Check if all shifted_minus_5 are lowercase letters
        if all('a' <= c <= 'z' for c in shifted_minus_5):
            # Input is likely encoded, decode by shifting -5
            shift = -5
        else:
            # Input is decoded, encode by shifting +5
            shift = 5

    return ''.join(shift_char(c, shift) for c in s)



