def monotonic(l: list):
    """
    Return True if the list elements are monotonic, i.e., entirely non-decreasing or entirely non-increasing.
    Sequences with equal consecutive elements are considered monotonic.

    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    >>> monotonic([1, 2, 2, 3])
    True
    """
    if len(l) < 2:
        return True
    non_decreasing = all(x <= y for x, y in zip(l, l[1:]))
    non_increasing = all(x >= y for x, y in zip(l, l[1:]))
    return non_decreasing or non_increasing



