def circular_shift(x, shift):
    s = str(abs(x))
    n = len(s)
    if abs(shift) > n:
        return s[::-1]
    if shift == 0 or n == 1:
        return s
    shift_mod = shift % n
    if shift > 0:
        # circular right shift
        return s[-shift_mod:] + s[:-shift_mod]
    else:
        # circular left shift
        shift_mod = (-shift) % n
        return s[shift_mod:] + s[:shift_mod]



