def smallest_change(arr):
    """
    Given an array arr of integers, determine the minimum number of elements that need to be changed 
    to make the array palindromic. A palindromic array reads the same forwards and backwards. 
    In one change, you can change one element to any other integer.

    The function should return 0 if the array is already palindromic or if the array is empty 
    (since an empty array is trivially palindromic).

    Examples:
    smallest_change([1,2,3,5,4,7,9,6]) == 4
    smallest_change([1, 2, 3, 4, 3, 2, 2]) == 1
    smallest_change([1, 2, 3, 2, 1]) == 0
    smallest_change([]) == 0
    """
    if not arr:
        return 0
    count = 0
    n = len(arr)
    for i in range(n // 2):
        if arr[i] != arr[n - 1 - i]:
            count += 1
    return count



