def prime_length(string):
    """
    Return True if the length of the input string is a prime number, and False otherwise.

    A prime number is a natural number greater than 1 that has no positive divisors other than 1 and itself.

    Examples:
    prime_length('Hello') == True   # length 5 is prime
    prime_length('abcdcba') == True # length 7 is prime
    prime_length('kittens') == True # length 7 is prime
    prime_length('orange') == False # length 6 is not prime
    """
    n = len(string)
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True



