def order_by_points(nums):
    """
    Sort the given list of integers in descending order according to the sum of their digits.
    If multiple items have the same sum of digits, maintain their original relative order.

    Note:
    - The sum of digits is calculated using the absolute value of each integer.
    - The sorting is stable with respect to the original list order for ties.

    For example:
    >>> order_by_points([1, 11, -1, -11, -12]) == [-12, 11, -11, 1, -1]
    >>> order_by_points([]) == []
    """
    def digit_sum(n):
        return sum(int(d) for d in str(abs(n)))
    return sorted(nums, key=digit_sum, reverse=True)



