from typing import List, Tuple

def parse_music(music_string: str) -> Tuple[List[int], str]:
    beat_map = {'o': 4, 'o|': 2, '.|': 1}

    notes = music_string.split()
    beats = list(map(beat_map.get, notes))

    count_o = notes.count('o')
    count_o_pipe = notes.count('o|')
    count_dot_pipe = notes.count('.|')

    counts = {'o': count_o, 'o|': count_o_pipe, '.|': count_dot_pipe}

    max_count = max(counts.values())
    candidates = [note for note, cnt in counts.items() if cnt == max_count]
    # Tie-break by longest beat duration
    most_common = max(candidates, key=lambda n: beat_map[n])

    return (beats, most_common)



