def monotonic(l):
    """Return a tuple (True, sum_or_concat) if the elements of the input are monotonically increasing or monotonically decreasing, allowing duplicates (i.e., non-strict monotonicity). Return False otherwise.

    For list inputs:
    - Return (True, total) where total is the integer sum of the list elements if the list is monotonically non-decreasing or monotonically non-increasing.
    - Return False if the list is not monotonic.

    For string inputs:
    - Return (True, original_string) if the characters are in strictly alphabetical order or strictly reverse alphabetical order without any duplicate characters.
    - Return False if the string is not monotonic.

    The function does not use any loops or in-built sorting methods.
    """
    if isinstance(l, list):
        def non_decreasing(seq):
            return all(x <= y for x, y in zip(seq, seq[1:]))
        def non_increasing(seq):
            return all(x >= y for x, y in zip(seq, seq[1:]))
        if non_decreasing(l) or non_increasing(l):
            return (True, sum(l))
        else:
            return False
    elif isinstance(l, str):
        if len(l) != len(set(l)):
            return False
        def strictly_increasing(seq):
            return all(x < y for x, y in zip(seq, seq[1:]))
        def strictly_decreasing(seq):
            return all(x > y for x, y in zip(seq, seq[1:]))
        if strictly_increasing(l) or strictly_decreasing(l):
            return (True, l)
        else:
            return False
    else:
        return False



