def total_match(lst1, lst2):
    if not lst1 and not lst2:
        return []
    is_int = (lambda l: all(isinstance(x, int) for x in l))
    if is_int(lst1) and is_int(lst2):
        digits = lambda l: sum(len(str(abs(x))) for x in l)
        d1, d2 = digits(lst1), digits(lst2)
        chosen = lst1 if d1 <= d2 else lst2
        return ' '.join(str(x) for x in chosen)
    # at least one list contains strings
    combined = lst1 + lst2
    longest = max(combined, key=lambda s: (len(s), -combined.index(s)) if isinstance(s, str) else (-1, 0))
    # max with key to get longest string; tie-break is first occurrence in lst1 then lst2
    # but max returns last max in case of ties, so invert index
    # so key: (length, -index) -> longest length, earliest index
    # filter only strings, else length= -1 to ignore ints if any
    # corner case: when combined has ints, they get length -1 so won't be chosen
    return longest



