def maximum(arr, k):
    if k == 0:
        return []
    # Use a selection algorithm to find k largest elements, then sort them ascending without built-in sort
    # Approach:
    # 1. Find k largest elements by partial selection
    # 2. Sort these k elements using insertion sort

    n = len(arr)
    # Step 1: Select k largest elements via repeated selection of max
    selected = []
    used_indices = set()
    for _ in range(k):
        max_val = None
        max_idx = None
        for i in range(n):
            if i in used_indices:
                continue
            val = arr[i]
            if max_val is None or val > max_val:
                max_val = val
                max_idx = i
        used_indices.add(max_idx)
        selected.append(max_val)

    # Step 2: Sort selected ascending using insertion sort
    for i in range(1, k):
        key = selected[i]
        j = i - 1
        while j >= 0 and selected[j] > key:
            selected[j + 1] = selected[j]
            j -= 1
        selected[j + 1] = key

    return selected



