def solve(s):
    has_letter = any(c.isalpha() for c in s)
    if has_letter:
        transformed = []
        for c in s:
            if c.islower():
                transformed.append(c.upper())
            elif c.isupper():
                transformed.append(c.lower())
            else:
                transformed.append(c)
        res_str = ''.join(transformed)
        try:
            return int(res_str)
        except ValueError:
            # If cannot convert to int, fallback: convert letters to their ASCII codes concatenated
            # and keep digits as is. For special chars, convert to their ASCII codes too.
            # Build a numeric string representing whole transformed string.
            numeric_str = ''
            for ch in res_str:
                if ch.isdigit():
                    numeric_str += ch
                else:
                    numeric_str += str(ord(ch))
            return int(numeric_str)
    else:
        reversed_str = s[::-1]
        return int(reversed_str)



