def maximum(arr, k):
    if k == 0:
        return []
    sorted_desc = sorted(arr, reverse=True)
    kth_value = sorted_desc[k-1]
    greater_count = sum(1 for x in arr if x > kth_value)
    kth_count_needed = k - greater_count
    result = [x for x in arr if x > kth_value]
    kth_values_added = 0
    for x in arr:
        if x == kth_value and kth_values_added < kth_count_needed:
            result.append(x)
            kth_values_added += 1
    return sorted(result)



