def parse_nested_parens(text):
    """
    The input to this routine is a string composed of several groups separated by whitespace.
    Each group may contain zero or more parentheses characters '(' and ')'.
    For each group, return an integer indicating the deepest nesting level of parentheses present in that group.
    The nesting level is defined as the maximum number of open parentheses that are nested inside each other at any point.
    Groups that contain no parentheses or are empty should be represented by 0 in the output list, indicating zero nesting.

    Examples:
    >>> parse_nested_parens('(()()) ((())) () ((())()())')
    [2, 3, 1, 3]

    >>> parse_nested_parens('()  ()')
    [1, 1]

    >>> parse_nested_parens(') (()) (abc) ()')
    [0, 2, 0, 1]
    """
    result = []
    groups = text.split()
    for group in groups:
        max_depth = 0
        current_depth = 0
        has_paren = False
        for ch in group:
            if ch == '(':
                current_depth += 1
                has_paren = True
                if current_depth > max_depth:
                    max_depth = current_depth
            elif ch == ')':
                # Only decrement if current_depth > 0 to avoid negative depth
                if current_depth > 0:
                    current_depth -= 1
                has_paren = True
        # If no parentheses at all, max_depth stays 0
        result.append(max_depth if has_paren else 0)
    return result



