def triples_sum_to_zero(items):
    """
    triples_sum_to_zero accepts a collection of values.
    It returns True if there exist three distinct elements at different positions (indices) in the collection
    whose sum is zero, and False otherwise.
    Elements with the same value can be used more than once only if they occur at different positions.

    >>> triples_sum_to_zero([1, 3, 5, 0])
    False
    >>> triples_sum_to_zero([1, 3, -2, 1])
    True
    >>> triples_sum_to_zero([1, 2, 3, 7])
    False
    >>> triples_sum_to_zero([2, 4, -5, 3, 9, 7])
    True
    >>> triples_sum_to_zero([1])
    False
    """
    n = len(items)
    if n < 3:
        return False
    items_sorted = sorted(items)
    for i in range(n - 2):
        a = items_sorted[i]
        left = i + 1
        right = n - 1
        while left < right:
            s = a + items_sorted[left] + items_sorted[right]
            if s == 0:
                return True
            elif s < 0:
                left += 1
            else:
                right -= 1
    return False



