def monotonic(seq):
    """
    Return True if the sequence is monotonic, meaning its items move consistently in one direction without reversing.
    A sequence is considered monotonic if it is entirely nondecreasing (each element is greater than or equal to the previous)
    or entirely nonincreasing (each element is less than or equal to the previous). Equal consecutive elements are allowed.

    Examples:
    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    >>> monotonic([1, 2, 2, 3])
    True
    """
    if len(seq) < 2:
        return True
    nondecreasing = all(seq[i] <= seq[i+1] for i in range(len(seq)-1))
    nonincreasing = all(seq[i] >= seq[i+1] for i in range(len(seq)-1))
    return nondecreasing or nonincreasing



