def anti_shuffle(t):
    result = []
    i = 0
    n = len(t)
    while i < n:
        if t[i] == ' ':
            result.append(' ')
            i += 1
        else:
            start = i
            while i < n and t[i] != ' ':
                i += 1
            word = t[start:i]
            sorted_word = ''.join(sorted(word))
            result.append(sorted_word)
    return ''.join(result)



