def max_fill(layout, limit):
    total_placements = 0
    for row in layout:
        ones = [i for i, val in enumerate(row) if val == 1]
        if not ones:
            continue
        n = len(ones)
        dp = [float('inf')] * (n + 1)
        dp[0] = 0
        for i in range(1, n + 1):
            for j in range(i):
                if ones[i - 1] - ones[j] + 1 <= limit:
                    dp[i] = min(dp[i], dp[j] + 1)
        total_placements += dp[n]
    return total_placements



