    Return True if the list is strictly monotonic, i.e., strictly increasing or strictly decreasing, and False otherwise.

    A list is strictly increasing if each element is greater than the preceding element.
    A list is strictly decreasing if each element is less than the preceding element.

    Examples:
    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    """
    if len(l) < 2:
        return True
    increasing = all(l[i] > l[i - 1] for i in range(1, len(l)))
    if increasing:
        return True
    decreasing = all(l[i] < l[i - 1] for i in range(1, len(l)))
    return decreasing



