from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    groups = paren_string.split()
    result = []
    for group in groups:
        max_depth = 0
        current_depth = 0
        has_paren = False
        has_non_paren_inside = False
        for ch in group:
            if ch == '(':
                has_paren = True
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif ch == ')':
                has_paren = True
                current_depth -= 1
            elif has_paren:
                # If we have encountered parentheses already and now see non-paren char,
                # mark that the group contains other chars inside parentheses.
                has_non_paren_inside = True
        # If there are parentheses but any non-paren chars inside group, max depth is 0
        # as per examples e.g. '(abc)' -> 0
        if has_paren and has_non_paren_inside:
            max_depth = 0
        # If group has no parentheses at all, max_depth stays 0 as required.
        result.append(max_depth)
    return result



