def parse_music(music_string: str) -> List[int]:
    """ 
    Parses a string representing musical notes in a special ASCII format and returns a list of integers 
    indicating the duration in beats of each note.

    The input string consists of space-separated tokens, each exactly equal to one of:
    - 'o'  : whole note, lasts 4 beats
    - 'o|' : half note, lasts 2 beats
    - '.|' : quarter note, lasts 1 beat

    Args:
