def triples_sum_to_zero(l: list):
    """
    triples_sum_to_zero takes a list of integers as input.
    It returns True if there exist three elements at distinct indices in the list
    whose values sum to zero, and False otherwise.
    The three elements must come from different positions in the list, but their values
    do not need to be distinct (i.e., repeated values are allowed as long as indices differ).

    >>> triples_sum_to_zero([1, 3, 5, 0])
    False
    >>> triples_sum_to_zero([1, 3, -2, 1])
    True
    >>> triples_sum_to_zero([1, 2, 3, 7])
    False
    >>> triples_sum_to_zero([2, 4, -5, 3, 9, 7])
    True
    >>> triples_sum_to_zero([1])
    False
    """
    n = len(l)
    if n < 3:
        return False
    l.sort()
    for i in range(n - 2):
        left, right = i + 1, n - 1
        while left < right:
            s = l[i] + l[left] + l[right]
            if s == 0:
                return True
            elif s < 0:
                left += 1
            else:
                right -= 1
    return False



