def monotonic(l: list):
    """Return True if the elements of the list are monotonically increasing or monotonically decreasing, allowing equal adjacent elements.

    A list is considered monotonically increasing if each element is greater than or equal to the previous element.
    Similarly, it is monotonically decreasing if each element is less than or equal to the previous element.

    Examples:
    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    >>> monotonic([1, 2, 2, 3])
    True
    """
    if not l:
        return True
    increasing = True
    decreasing = True
    for i in range(1, len(l)):
        if l[i] < l[i - 1]:
            increasing = False
        if l[i] > l[i - 1]:
            decreasing = False
        if not increasing and not decreasing:
            return False
    return True



