def monotonic(lst):
    """
    Return True if the elements of the list are monotonically increasing or monotonically decreasing,
    allowing equality between adjacent elements (i.e., non-strict monotonicity).
    In other words, the function returns True if the sequence is entirely non-decreasing
    (each element is greater than or equal to the previous one) or entirely non-increasing
    (each element is less than or equal to the previous one).

    Examples:
    >>> monotonic([1, 2, 2, 3])
    True
    >>> monotonic([3, 2, 2, 1])
    True
    >>> monotonic([1, 3, 2])
    False
    >>> monotonic([1, 1, 2])
    True
    """
    if not lst:
        return True
    non_decreasing = all(x <= y for x, y in zip(lst, lst[1:]))
    non_increasing = all(x >= y for x, y in zip(lst, lst[1:]))
