def move_one_ball(arr):
    """
    Given an array 'arr', determine if it is possible to obtain a sorted array in non-decreasing order 
    by performing any number of right shift operations. A right shift operation is defined as rotating 
    the entire array by one position to the right, moving the last element to the front.

    Return True if it is possible to get the array sorted by applying zero or more right shifts; 
    otherwise, return False.

    If the array is empty, return True.

    Examples:
    move_one_ball([3, 4, 5, 1, 2]) == True
    move_one_ball([3, 5, 4, 1, 2]) == False
    """
    if not arr:
        return True
    n = len(arr)
    count_breaks = 0
    for i in range(n):
        if arr[i] > arr[(i+1) % n]:
            count_breaks += 1
            if count_breaks > 1:
                return False
    return True



