def parse_music(music: str) -> list[int]:
    """
    Parse a piece of music given as a string and return a list of durations in beats corresponding to each symbol in the input.

    Each symbol in the input string represents a musical element whose duration in beats is to be extracted. The function processes the input string symbol by symbol and outputs a list of integers (or floats if needed) where each element corresponds to the duration in beats of the respective symbol.

    Parameters:
        music (str): A string representing a piece of music, where each symbol encodes a note, rest, or other musical event.

    Returns:
        list[int]: A list of durations in beats, one for each symbol in the input string, reflecting the parsed durations.

    Examples:
        >>> parse_music("A B C")
        [1, 1, 1]
        >>> parse_music("A2 B4 C1")
        [2, 4, 1]
    """
    durations = []
    for symbol in music.split():
        # Separate the note part and the duration part
        # The note is the leading non-digit characters, duration is the trailing digits if any
        i = 0
        while i < len(symbol) and not symbol[i].isdigit():
            i += 1
        duration_part = symbol[i:]
        if duration_part == '':
            # No explicit duration: default 1
            durations.append(1)
        else:
            # Parse the duration part as int or float if needed
            # Spec examples show integers, so int is sufficient
            try:
                dur = int(duration_part)
            except ValueError:
                # fallback: try float if needed, but spec examples imply int only
                dur = float(duration_part)
            durations.append(dur)
    return durations



