def move_one_ball(arr):
    if not arr:
        return True
    n = len(arr)
    # Count the number of drops where arr[i] > arr[i+1]
    drops = 0
    drop_index = -1
    for i in range(n - 1):
        if arr[i] > arr[i + 1]:
            drops += 1
            drop_index = i
            if drops > 1:
                return False
    # If no drops, already sorted
    if drops == 0:
        return True
    # Check if the last element is <= first element (to complete the rotation)
    if arr[-1] > arr[0]:
        return False
    # If exactly one drop, the rotation start is drop_index + 1
    # Rotation by moving last element to front each time means rotation start index = drop_index + 1
    # Since all elements are distinct, this guarantees strict increasing order after rotation
    return True



