def anti_shuffle(s):
    import re

    # Split the string into sequences of spaces and non-spaces
    parts = re.findall(r'\s+|\S+', s)
    result = []

    for part in parts:
        if part.isspace():
            # Spaces are preserved as is
            result.append(part)
        else:
            # Sort characters of the word (letters + adjacent punctuation) by ASCII
            sorted_part = ''.join(sorted(part))
            result.append(sorted_part)

    return ''.join(result)



