def anti_shuffle(s):
    import re
    result = []
    # Split by spaces, preserving them by splitting on word boundaries including spaces
    tokens = re.findall(r'\S+|\s+', s)
    for token in tokens:
        if token.isspace():
            # preserve spaces exactly
            result.append(token)
            continue
        word = token
        # Find trailing non-alphabetic characters
        i = len(word)
        while i > 0 and not word[i-1].isalpha():
            i -= 1
        trailing = word[i:]
        core = word[:i]
        # Sort only alphabetic characters descending ASCII in core
        # Internal non-alphabetic characters in core remain as is (per spec unresolved)
        # So we must identify alphabetic chars to sort, and keep other chars in place
        # But spec is ambiguous about internal non-alpha chars - test_7 removed or invalid.
        # So we treat all core chars and sort only alphabetic chars, leaving others in place.
        # Spec says "sort all alphabetic characters", trailing non-alpha excluded, so internal non-alpha stay in place.
        # So we separate alphabetic chars, sort descending, then place them back in the original positions of alphabetic chars.
        core_chars = list(core)
        alpha_positions = [i for i,c in enumerate(core_chars) if c.isalpha()]
        alpha_chars = [core_chars[i] for i in alpha_positions]
        alpha_chars.sort(reverse=True)
        for pos, ch in zip(alpha_positions, alpha_chars):
            core_chars[pos] = ch
        new_word = ''.join(core_chars) + trailing
        result.append(new_word)
    return ''.join(result)



