def monotonic(l: list):
    """
    Return True if the list elements are monotonic (either entirely non-decreasing or entirely non-increasing), and False otherwise.

    A list is monotonic if for every pair of consecutive elements, the sequence never increases after decreasing or never decreases after increasing.

    Examples:
    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    """
    if len(l) <= 1:
        return True
    non_decreasing = True
    non_increasing = True
    for i in range(1, len(l)):
        if l[i] < l[i - 1]:
            non_decreasing = False
        if l[i] > l[i - 1]:
            non_increasing = False
        if not non_decreasing and not non_increasing:
            return False
    return True



