def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)
    if all(ch == '9' for ch in s):
        # If all 9's, next palindrome is 10..01 (length + 1)
        return int('1' + ('0' * (length - 1)) + '1')

    def make_palindrome(left: str, odd_length: bool) -> int:
        if odd_length:
            return int(left + left[:-1][::-1])
        else:
            return int(left + left[::-1])

    half_len = (length + 1) // 2
    left = s[:half_len]
    odd_length = (length % 2 != 0)

    palindrome = make_palindrome(left, odd_length)
    if palindrome > n:
        return palindrome

    # Increment the left part and then mirror again
    left_num = int(left)
    left_num += 1
    left_str = str(left_num)
    # If incrementing left causes length increase (e.g. 999 -> 1000)
    if len(left_str) > len(left):
        # Means the palindrome length should increase by 1
        # For example, 999 -> 1001, length 3 -> 4
        return int('1' + ('0' * (length -1)) + '1')
    return make_palindrome(left_str, odd_length)



