def find_solution(a, b, n):
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else "No solution"
    if a == 0:
        if b != 0 and n % b == 0 and n // b >= 0:
            return (0, n // b)
        return "No solution"
    if b == 0:
        if a != 0 and n % a == 0 and n // a >= 0:
            return (n // a, 0)
        return "No solution"
    if n < 0:
        return "No solution"
    x = 0
    while a * x <= n:
        rem = n - a * x
        if rem % b == 0:
            y = rem // b
            if y >= 0:
                return (x, y)
        x += 1
    return "No solution"



