def decode_list(lst):
    result = []
    for el in lst:
        if isinstance(el, list) and len(el) == 2:
            count, value = el
            if isinstance(count, int) and count > 0:
                result.extend([value] * count)
            elif isinstance(count, int) and count <= 0:
                # zero or negative count means skip adding
                continue
            else:
                # count not int, treat el as standalone
                result.append(el)
        else:
            result.append(el)
    return result



