def get_total_number_of_sequences(n: int, m: int) -> int:
    if n <= 0 or m <= 0:
        # No sequences of length <=0 or max element <=0
        return 0
    # dp[i][x] = number of sequences of length i ending with value x
    # For i=1, dp[1][x] = 1 for x in [1..m]
    dp_prev = [0] + [1] * m  # 1-based indexing: dp_prev[x]
    for length in range(2, n + 1):
        dp_curr = [0] * (m + 1)
        # prefix sums to efficiently sum dp_prev[y] for y >= 2*x
        prefix_sum = [0] * (m + 2)
        for v in range(m, 0, -1):
            prefix_sum[v] = prefix_sum[v + 1] + dp_prev[v]
        for x in range(1, m + 1):
            min_next = 2 * x
            if min_next <= m:
                dp_curr[x] = prefix_sum[min_next]
            else:
                dp_curr[x] = 0
        dp_prev = dp_curr
    return sum(dp_prev[1:])



