def even_binomial_Coeff_Sum(n: int) -> int:
    """
    Calculate the sum of all binomial coefficients for a given integer n.

    Specifically, this function returns the sum of the binomial coefficients
    \( \binom{n}{k} \) for all k from 0 to n, inclusive. Mathematically, this sum
    is equal to \( 2^n \).

    Parameters:
    ----------
    n : int
        A non-negative integer representing the upper index in the binomial coefficients.

    Returns:
    -------
    int
        The sum of all binomial coefficients \( \binom{n}{k} \) for k=0 to n,
        which is \( 2^n \).

    Examples:
    --------
    >>> even_binomial_Coeff_Sum(0)
    1

    >>> even_binomial_Coeff_Sum(3)
    8

    >>> even_binomial_Coeff_Sum(5)
    32
    """
    return 2 ** n



