def remove_column(matrix: list[list], col_idx: int) -> list[list]:
    result = []
    for row in matrix:
        # Validate index; allow negative indices as per Python list indexing rules
        if not (-len(row) <= col_idx < len(row)):
            raise IndexError("list index out of range")
        # Construct new row without the element at col_idx
        new_row = row[:col_idx] + row[col_idx+1:]
        result.append(new_row)
    return result



