def find_remainder(a: int, b: int, n: int) -> int:
    """
    Calculate the remainder when the product of two integers a and b is divided by n.

    The function performs modular multiplication by taking the modulo n after multiplying each operand
    to safely handle large integers and avoid overflow. Specifically, it computes ((a % n) * (b % n)) % n.

    Parameters:
    - a (int): The first integer.
    - b (int): The second integer.
    - n (int): The divisor.

    Returns:
    - int: The remainder of (a * b) divided by n using modular multiplication.

    Examples:
    >>> find_remainder(10, 5, 6)
    2
    >>> find_remainder(123456789, 987654321, 1000000007)
    259106859
    """
    a_mod = a % n
    b_mod = b % n
    return (a_mod * b_mod) % n



