def find_Max(nums: list[int]) -> int:
    left, right = 0, len(nums) - 1
    while left < right:
        mid = (left + right) // 2
        if nums[mid] > nums[right]:
            left = mid + 1
        else:
            right = mid
    # left is now the index of the smallest element, max is before it (or at end if no rotation)
    return nums[left - 1] if left > 0 else nums[-1]



