import re

def capital_words_spaces(s: str) -> str:
    # Insert space before uppercase letter if preceded by a word character,
    # but keep consecutive uppercase letters together as a block.
    # The regex uses a lookbehind for a word character,
    # and a lookahead for an uppercase letter followed by a lowercase letter (start of new word),
    # or an uppercase letter preceded by a lowercase letter or digit (start of uppercase block).
    # We insert space before uppercase letter that starts a new block.
    def repl(m):
        return ' ' + m.group(0)
    # Pattern explanation:
    # (?<=\w) : preceded by word char
    # (?=[A-Z]) : uppercase letter ahead
    # We want to insert space before uppercase letter if:
    # - preceded by word char
    # - and the uppercase letter is start of a block:
    #   that is, either:
    #    a) uppercase letter followed by lowercase letter (start of capitalized word)
    #    b) uppercase letter preceded by lowercase letter or digit (start of uppercase block after lowercase/digit)
    # Because consecutive uppercase letters stay together, we only insert before first uppercase in block.
    # We simplify by inserting space before uppercase letter preceded by word char and preceded by a lowercase/digit or preceded by uppercase but next after lowercase.
    #
    # Instead, to keep it simple and correct per spec, insert space before uppercase letter preceded by word char,
    # and not preceded by uppercase letter (to keep uppercase blocks intact).
    #
    # So pattern: (?<=\w)(?<![A-Z])([A-Z])
    # meaning uppercase letter preceded by word char, but not preceded by uppercase letter.
    return re.sub(r'(?<=\w)(?<![A-Z])([A-Z])', repl, s)



