def dif_Square(n: int) -> bool:
    # n = a^2 - b^2 = (a-b)(a+b)
    # Let x = a-b and y = a+b, then n = x*y
    # For a,b integer: (x+y) and (y-x) must be even, so x and y have same parity.
    # So n can be represented as difference of squares iff n has a factorization into two integers of the same parity.
    if n == 0:
        return True  # 0 = 0^2 - 0^2
    for x in range(1, abs(n) + 1):
        if n % x == 0:
            y = n // x
            if (x + y) % 2 == 0:
                return True
            if (-x + (-y)) % 2 == 0:
                return True
    return False



