def next_smallest_palindrome(n: int) -> int | None:
    if n <= 1:
        return None
    s = str(n - 1)
    length = len(s)

    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    # Try decrementing down from n-1 to find palindrome
    # but this can be slow for large n, so use a constructive approach

    # Construct palindrome candidates based on the left half
    half_len = (length + 1) // 2

    left = int(s[:half_len])
    candidates = []

    # Generate palindromes by mirroring left half and its neighbors
    for diff in (0, -1, 1):
        new_left = left + diff
        if new_left < 0:
            continue
        new_left_str = str(new_left)
        if length % 2 == 0:
            pal_str = new_left_str + new_left_str[::-1]
        else:
            pal_str = new_left_str + new_left_str[-2::-1]
        pal_num = int(pal_str)
        if pal_num < n:
            candidates.append(pal_num)

    # Also consider palindromes with length-1 digits (all 9's)
    if length > 1:
        candidates.append(int("9" * (length - 1)))

    # Filter valid candidates smaller than n
    candidates = [c for c in candidates if c < n]

    if not candidates:
        return None
    return max(candidates)



