def find_solution(a, b, n):
    if b == 0:
        return "No solution"
    x = 0
    while True:
        remainder = n - a * x
        if remainder % b == 0:
            y = remainder // b
            return (x, y)
        x += 1
        # To avoid infinite loop in case no solution exists,
        # break when x exceeds a reasonable limit.
        # But spec does not specify upper bound, so we rely on integer arithmetic:
        # If b divides gcd(a,b), solution exists; else no solution.
        # Since no gcd check allowed by spec, try up to abs(n) + abs(a) + abs(b) as heuristic.
        if x > abs(n) + abs(a) + abs(b) + 1000:
            break
    return "No solution"



