def get_total_number_of_sequences(n: int, m: int) -> int:
    if n == 0 or m == 0:
        return 0
    if n == 1:
        return m if m > 0 else 0

    from functools import lru_cache

    @lru_cache(None)
    def count_sequences(pos: int, prev: int) -> int:
        if pos == n:
            return 1
        total = 0
        start = 2 * prev
        if start > m:
            return 0
        for val in range(start, m + 1):
            total += count_sequences(pos + 1, val)
        return total

    total_count = 0
    for first_val in range(1, m + 1):
        total_count += count_sequences(1, first_val)
    return total_count



