def remove_column(nested_list, col_index):
    """
    Remove the specified column from each inner list of the given nested list.

    Parameters:
    - nested_list: A list of lists, where inner lists may have varying lengths.
    - col_index: An integer representing the zero-based index of the column to remove.

    Returns:
    A new nested list where each inner list has the element at col_index removed,
    if that element exists. Inner lists shorter than col_index + 1 are left unchanged.

    Notes:
    - The input nested list may be irregular; inner lists can have different lengths.
    - For any inner list that does not have an element at col_index, that inner list
      is returned unchanged (no error is raised).

    Examples:
    >>> remove_column([[1, 2, 3], [4, 5, 6], [7, 8, 9]], 1)
    [[1, 3], [4, 6], [7, 9]]

    >>> remove_column([[1, 2, 3], [4, 5], [6, 7, 8]], 2)
    [[1, 2], [4, 5], [6, 7]]
    """
    result = []
    for inner in nested_list:
        if len(inner) > col_index:
            result.append(inner[:col_index] + inner[col_index+1:])
        else:
            result.append(inner[:])
    return result



