def permute_string(s: str) -> list[str]:
    from collections import Counter

    def backtrack(path, counter, length, result):
        if len(path) == length:
            result.append("".join(path))
            return
        for char in counter:
            if counter[char] > 0:
                counter[char] -= 1
                path.append(char)
                backtrack(path, counter, length, result)
                path.pop()
                counter[char] += 1

    result = []
    counter = Counter(s)
    backtrack([], counter, len(s), result)
    return result



