def sum_Of_product(n: int) -> int:
    if not isinstance(n, int):
        raise TypeError("Input must be an integer")
    if n < 0:
        # Either raise or handle gracefully; here we raise
        raise ValueError("Input must be non-negative")
    from math import comb
    # sum_{k=0}^n sum_{i=0}^k C(n,i)*C(n,k-i)
    # Simplify inner sum: sum_{i=0}^k C(n,i)*C(n,k-i) = C(2n,k) by Vandermonde's identity
    # So total sum = sum_{k=0}^n C(2n,k)
    total = 0
    for k in range(n+1):
        total += comb(2*n, k)
    return total



