def str_to_tuple(s: str) -> tuple:
    import re
    if not s.strip():
        return ()
    # Try common separators in order of likelihood
    for sep in [',', ' ', ';', '|']:
        if sep in s:
            tokens = s.split(sep)
            break
    else:
        tokens = [s]
    result = []
    for token in tokens:
        token = token.strip()
        if not token:
            continue
        # parse number as int if possible, else float
        try:
            val = int(token)
        except ValueError:
            val = float(token)
        result.append(val)
    return tuple(result)



