def length_Of_Last_Word(s: str) -> int:
    s = s.rstrip()
    i = len(s) - 1
    # Skip trailing non-alphabetic characters
    while i >= 0 and not s[i].isalpha():
        i -= 1
    if i < 0:
        return 0
    end = i
    # Find start of the last word (alphabetic sequence)
    while i >= 0 and s[i].isalpha():
        i -= 1
    start = i + 1
    return end - start + 1



