def substract_elements(coll):
    if isinstance(coll, list):
        # Check if all elements are numbers (int or float)
        if all(isinstance(x, (int, float)) for x in coll):
            # Compute differences between consecutive numeric elements
            return [coll[i+1] - coll[i] for i in range(len(coll)-1)]
        else:
            # Mixed or nested list: process each element
            result = []
            for el in coll:
                if isinstance(el, list):
                    # Recursively process sublist
                    result.append(substract_elements(el))
                else:
                    # Non-list element replaced by empty list
                    result.append([])
            return result
    else:
        # Not a list: per spec, input is nested lists, so no other case expected
        return []



