def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)
    if all(ch == '9' for ch in s):
        # If all digits are 9, the next palindrome is 10..01 with length+1
        return int('1' + ('0' * (length - 1)) + '1')
    # Helper to create palindrome by mirroring the left half to right
    def make_palindrome(left: str, odd_length: bool) -> int:
        if odd_length:
            return int(left + left[:-1][::-1])
        else:
            return int(left + left[::-1])
    half_len = (length + 1) // 2
    left = s[:half_len]
    # Construct palindrome by mirroring left
    pal = make_palindrome(left, length % 2 != 0)
    if pal > n:
        return pal
    # Increment the left half and mirror again
    left_int = int(left) + 1
    left_str = str(left_int)
    # If incrementing causes length increase, e.g. 999 -> 1000
    if len(left_str) > len(left):
        # For cases like 999 -> 1000, the palindrome must be of length+1
        # So return 10..01 with length+1 digits
        return int('1' + ('0' * (length - 1)) + '1')
    return make_palindrome(left_str, length % 2 != 0)



