def sort_sublists(lists):
    def equal_prefix(s1, s2):
        min_len = min(len(s1), len(s2))
        return s1[:min_len] == s2[:min_len]

    def cmp_key(s):
        return s

    def stable_sort_with_equal_prefix(lst):
        n = len(lst)
        if n <= 1:
            return lst[:]
        # Perform a stable sort with the constraint that equal-prefix strings keep original order
        # We use a modified merge sort that does not reorder equal-prefix strings relative to each other

        def merge(left, right):
            result = []
            i = j = 0
            while i < len(left) and j < len(right):
                if left[i] < right[j]:
                    # left[i] < right[j], so left[i] goes first
                    result.append(left[i])
                    i += 1
                elif left[i] > right[j]:
                    # left[i] > right[j], so right[j] goes first
                    result.append(right[j])
                    j += 1
                else:
                    # left[i] == right[j] lex order, treat as equal-prefix
                    # preserve original order: take from left first, then right
                    # But to confirm equal-prefix, check prefixes:
                    if equal_prefix(left[i], right[j]):
                        # equal-prefix, preserve original order by taking left[i] first
                        result.append(left[i])
                        i += 1
                    else:
                        # They are lex equal but not equal-prefix? That cannot happen.
                        # Fallback: take left[i] first for stability
                        result.append(left[i])
                        i += 1
            result.extend(left[i:])
            result.extend(right[j:])
            return result

        def merge_sort(arr):
            if len(arr) <= 1:
                return arr[:]
            mid = len(arr) // 2
            left = merge_sort(arr[:mid])
            right = merge_sort(arr[mid:])
            return merge(left, right)

        return merge_sort(lst)

    # Because the stable built-in sort cannot be customized to keep equal-prefix order except by normal stable sort,
    # and equal-prefix strings are those that compare equal up to the length of the shorter string,
    # to preserve order among equal-prefix strings, we must group equal-prefix strings into blocks and sort blocks.

    # Instead, we must implement custom comparator that treats equal-prefix strings as equal,
    # so that stable sorting preserves their original order.

    # Since Python's sort does not accept custom comparator (only key), we simulate comparator by key transformation.

    # Idea:
    # For each string, map it to a tuple: (string, index)
    # The sort key is the string itself
    # But when comparing two strings s1, s2:
    # if equal_prefix(s1, s2), treat them equal (sort key identical)
    # else normal lex order

    # We cannot achieve this via key function directly because key returns a value and not pairwise.

    # Instead, implement a custom stable merge sort with comparator as described.

    def cmp(s1, s2):
        if equal_prefix(s1, s2):
            return 0
        return -1 if s1 < s2 else 1

    def merge_with_cmp(left, right):
        result = []
        i = j = 0
        while i < len(left) and j < len(right):
            c = cmp(left[i], right[j])
            if c == -1:
                result.append(left[i])
                i += 1
            elif c == 1:
                result.append(right[j])
                j += 1
            else:
                # equal-prefix: preserve original order, left[i] first
                result.append(left[i])
                i += 1
        result.extend(left[i:])
        result.extend(right[j:])
        return result

    def merge_sort_with_cmp(arr):
        if len(arr) <= 1:
            return arr[:]
        mid = len(arr) // 2
        left = merge_sort_with_cmp(arr[:mid])
        right = merge_sort_with_cmp(arr[mid:])
        return merge_with_cmp(left, right)

    return [merge_sort_with_cmp(sublist) for sublist in lists]



