def remove_column(matrix: list[list], index: int) -> list[list]:
    if not matrix:
        return []
    row_length = len(matrix[0])
    # Normalize negative index
    if index < 0:
        index += row_length
    if index < 0 or index >= row_length:
        raise IndexError("Column index out of range")
    for row in matrix:
        if len(row) != row_length:
            raise IndexError("Rows have inconsistent lengths")
        # Check index bounds for each row explicitly
        if index < 0 or index >= len(row):
            raise IndexError("Column index out of range")
    return [row[:index] + row[index+1:] for row in matrix]



