from itertools import permutations

def permute_string(s: str) -> list[str]:
    # Sort input to ensure deterministic lex order of permutations
    sorted_s = ''.join(sorted(s))
    # Generate all permutations in lex order by using sorted input
    # Then sort permutations lex to ensure duplicates appear consecutively and in required order
    perms = [''.join(p) for p in permutations(sorted_s)]
    # We must reorder to match expected order with duplicates grouped as in test_1:
    # Actually, itertools.permutations produces permutations in lex order if input is sorted,
    # but duplicates appear in a different order than test_1 expects.
    # Test_1 expects ['aab', 'aab', 'aba', 'aba', 'baa', 'baa']
    # But itertools.permutations(sorted_s) produces:
    # ['aab', 'aba', 'aab', 'aba', 'baa', 'baa']
    # So we need to reorder to group duplicates pairs.
    # We can achieve this by sorting by the tuple (char counts, permutation), but that is complex.
    # However, test_1 expects duplicates to be adjacent duplicates, e.g. 'aab', 'aab', 'aba', 'aba', ...
    # The difference is that the two 'aab' permutations appear consecutively,
    # but itertools returns 'aab' then 'aba' then 'aab', then 'aba'.
    # The itertools order is: aab, aba, aab, aba, baa, baa
    # Expected order: aab, aab, aba, aba, baa, baa
    # So we just need to group identical strings together, preserving the order of first occurrence.
    # We'll count occurrences and reorder accordingly:
    from collections import defaultdict
    counts = defaultdict(int)
    for p in perms:
        counts[p] += 1
    # To preserve order but group duplicates, we can sort by (string, count index)
    # Build a dict mapping string to list of indices
    indices_map = defaultdict(list)
    for i, p in enumerate(perms):
        indices_map[p].append(i)
    # Now create grouped list by string order of first appearance in perms
    seen = set()
    result = []
    for p in perms:
        if p not in seen:
            # Add all occurrences of p in order of appearance
            for idx in indices_map[p]:
                result.append(perms[idx])
            seen.add(p)
    return result



