def add_string(format_string, items):
    # Count substitution slots "{}" excluding escaped braces "{{" and "}}"
    count = 0
    i = 0
    length = len(format_string)
    while i < length:
        if format_string[i] == '{':
            if i + 1 < length:
                if format_string[i + 1] == '{':
                    i += 2  # skip escaped brace
                    continue
                # Check for substitution slot start
                # Find matching closing brace
                j = i + 1
                while j < length:
                    if format_string[j] == '}':
                        if j + 1 < length and format_string[j + 1] == '}':
                            j += 2  # skip escaped closing brace
                            continue
                        # Found a substitution slot
                        count += 1
                        i = j
                        break
                    elif format_string[j] == '{':
                        # nested brace, treat as literal start, break
                        break
                    else:
                        j += 1
            i += 1
        elif format_string[i] == '}':
            if i + 1 < length and format_string[i + 1] == '}':
                i += 2  # escaped closing brace
            else:
                i += 1
        else:
            i += 1

    if count == 1:
        return [format_string.format(item) for item in items]
    else:
        return [format_string + str(item) for item in items]



