def find_Max(arr):
    """
    Given a sorted and rotated array `arr`, return the minimum element in the array.

    Parameters:
    - arr (list): A list of integers that was originally sorted in ascending order and then rotated.

    Returns:
    - int or None: The minimum element in the array if it is non-empty; if the array is empty, return None.
      If all elements in the array are identical, return that identical element.

    Examples:
    >>> find_Max([4,5,6,7,0,1,2])
    0
    >>> find_Max([3,4,5,1,2])
    1
    >>> find_Max([1,2,3,4,5])
    1
    >>> find_Max([2,2,2,2])
    2
    >>> find_Max([])
    None
    """
    if not arr:
        return None
    if all(x == arr[0] for x in arr):
        return arr[0]

    low, high = 0, len(arr) - 1
    while low < high:
        mid = (low + high) // 2
        if arr[mid] > arr[high]:
            low = mid + 1
        elif arr[mid] < arr[high]:
            high = mid
        else:  # arr[mid] == arr[high], handle duplicates
            high -= 1
    return arr[low]



