def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    # Special case: if all digits are '9', next palindrome is 10...01
    if all(ch == '9' for ch in s):
        return int('1' + ('0' * (length - 1)) + '1')

    def make_palindrome(left: str, odd_len: bool) -> int:
        if odd_len:
            return int(left + left[:-1][::-1])
        else:
            return int(left + left[::-1])

    odd_len = (length % 2 != 0)
    mid = length // 2

    if odd_len:
        left = s[:mid + 1]
    else:
        left = s[:mid]

    palindrome = make_palindrome(left, odd_len)
    if palindrome > num:
        return palindrome

    # Increment the left half (including middle if odd)
    if odd_len:
        left_num = int(left)
        left_num += 1
        left = str(left_num)
        # If length changed after increment, rebuild palindrome accordingly
        if len(left) > (mid + 1):
            # e.g. 999 -> after increment left becomes 1000, so palindrome length increases
            # Construct palindrome for new length
            return int('1' + ('0' * (length - 1)) + '1')
        palindrome = make_palindrome(left, odd_len)
    else:
        left_num = int(left)
        left_num += 1
        left = str(left_num)
        if len(left) > mid:
            return int('1' + ('0' * (length - 1)) + '1')
        palindrome = make_palindrome(left, odd_len)

    return palindrome



