import math

def find_solution(a: int, b: int, n: int):
    # Handle the trivial case where both a and b are zero
    if a == 0 and b == 0:
        if n == 0:
            return (0, 0)
        else:
            return None

    gcd = math.gcd(a, b)
    if n % gcd != 0:
        return None

    # Extended Euclidean Algorithm to find x0, y0 such that a*x0 + b*y0 = gcd
    def extended_gcd(aa, bb):
        if bb == 0:
            return (aa, 1, 0)
        else:
            g, x1, y1 = extended_gcd(bb, aa % bb)
            x = y1
            y = x1 - (aa // bb) * y1
            return (g, x, y)

    g, x0, y0 = extended_gcd(a, b)
    # Scale the solution to the desired n
    factor = n // g
    x = x0 * factor
    y = y0 * factor

    return (x, y)



