def get_total_number_of_sequences(n: int, m: int) -> int:
    if n == 0:
        # By interpretation, one empty sequence or none; here return 1 as empty sequence count
        return 1
    if n == 1:
        return m if m >= 1 else 0
    if m == 0:
        return 0

    # dp[i][x]: number of sequences of length i with last element x
    dp = [0] * (m + 1)
    for x in range(1, m + 1):
        dp[x] = 1

    for length in range(2, n + 1):
        new_dp = [0] * (m + 1)
        # prefix sums for dp to allow O(1) range sums
        prefix = [0] * (m + 2)
        for x in range(1, m + 1):
            prefix[x] = prefix[x - 1] + dp[x]
        for x in range(1, m + 1):
            start = 2 * x
            if start > m:
                new_dp[x] = 0
            else:
                # sum of dp[y] for y in [start, m]
                new_dp[x] = prefix[m] - prefix[start - 1]
        dp = new_dp

    return sum(dp[1:]) if m >= 1 else 0



