def even_binomial_Coeff_Sum(n: int) -> int:
    # Compute sum of binomial coefficients at even indices in nth row of Pascal's triangle
    # The nth row has coefficients C(n, 0), C(n, 1), ..., C(n, n)
    # Sum even indices: sum_{k=0..n, k even} C(n,k)
    # We compute each C(n,k) for even k using iterative formula without imports.
    def binomial(n, k):
        c = 1
        for i in range(1, k+1):
            c = c * (n - i + 1) // i
        return c

    total = 0
    for k in range(0, n+1, 2):
        total += binomial(n, k)
    return total



