def find_Max(arr):
    """
    Given a sorted and rotated array `arr` of integers, which may contain duplicate elements,
    return the maximum element in the array.

    The input array is originally sorted in non-decreasing order and then rotated an unknown number of times.
    The function must handle arrays with or without duplicate elements.

    Parameters:
    arr (list of int): A non-empty list of integers representing a sorted and rotated array.

    Returns:
    int: The maximum element in the array.

    Examples:
    >>> find_Max([4,5,6,7,0,1,2])
    7
    >>> find_Max([2,2,2,3,4,2])
    4
    >>> find_Max([1])
    1
    """
    left, right = 0, len(arr) - 1
    while left < right:
        mid = (left + right) // 2
        if arr[mid] > arr[right]:
            left = mid + 1
        elif arr[mid] < arr[right]:
            right = mid
        else:
            right -= 1
    # left is the index of smallest element (rotation point)
    return arr[left - 1] if left > 0 else arr[-1]



