def sum_Of_product(n):
    def comb(n, k):
        if k < 0 or k > n:
            return 0
        if k > n - k:
            k = n - k
        result = 1
        for i in range(1, k + 1):
            result = result * (n - i + 1) // i
        return result
    total = 0
    for k in range(n + 1):
        total += comb(n, k) * comb(n, k - 1)
    return total



