def lucky_num(n):
    if n <= 0:
        return []
    numbers = list(range(1, 2 * n * n))  # oversize to ensure enough lucky numbers
    idx = 1
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th number starting from step-1 index (0-based)
        numbers = [num for i, num in enumerate(numbers) if (i + 1) % step != 0]
        idx += 1
        if len(numbers) >= n and idx >= n:  # optimization: stop if enough lucky numbers obtained and sieve step reached at least n
            break
    return numbers[:n]



