def get_noOfways(width: int, height: int) -> int:
    if width < 0 or height < 0:
        return 0
    if width == 0 and height == 0:
        return 1
    area = width * height
    if area % 2 != 0:
        return 0
    # Use smaller dimension as width for efficiency
    w, h = min(width, height), max(width, height)
    if w == 0:
        return 1
    if w == 1:
        return 1

    from functools import lru_cache

