            if pos + 1 < w and (mask & (1 << (pos + 1))) == 0:
                res += fill_row(pos + 2, mask | (1 << pos) | (1 << (pos + 1)), next_mask)
            # Place vertical domino if possible (pos free in mask and mark pos in next_mask)
            res += fill_row(pos + 1, mask | (1 << pos), next_mask | (1 << pos))
