def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    # Handle all 9's case: next palindrome is 10..01
    if all(ch == '9' for ch in s):
        return int('1' + ('0' * (length - 1)) + '1')

    def mirror_left_to_right(s):
        l = len(s)
        half = l // 2
        if l % 2 == 0:
            return s[:half] + s[:half][::-1]
        else:
            return s[:half + 1] + s[:half][::-1]

    # Generate palindrome by mirroring left to right
    palindrome = mirror_left_to_right(s)
    if int(palindrome) > num:
        return int(palindrome)

    # Need to increment the middle part and then mirror again
    s_list = list(s)
    mid = (length - 1) // 2

    # Increment middle digit(s) and handle carry
    # For odd length: increment s[mid]
    # For even length: increment s[mid] and s[mid+1] as a combined number
    # We'll treat left half + middle as a number and increment it
    if length % 2 == 0:
        left_part = s[:length // 2]
        incremented = str(int(left_part) + 1)
        # If incremented length > left_part length, means carry-over increased length
        if len(incremented) > len(left_part):
            # e.g. 99 -> increment left half 9 + 1 = 10, length increased
            # so palindrome is 1 + '0' * (length-1) + 1
            return int('1' + ('0' * (length - 1)) + '1')
        palindrome = incremented + incremented[::-1]
    else:
        left_part = s[:mid + 1]
        incremented = str(int(left_part) + 1)
        if len(incremented) > len(left_part):
            return int('1' + ('0' * (length - 1)) + '1')
        palindrome = incremented + incremented[:-1][::-1]

    return int(palindrome)



