def next_power_of_2(number):
    if number < 1:
        raise ValueError("Input must be a positive integer")
    if number == 1:
        return 1
    max_k = 1
    # Maximum k is limited by log2(number) since smallest base is 2
    import math
    max_possible_k = int(math.log2(number)) + 1
    for k in range(max_possible_k, 1, -1):
        root = round(number ** (1 / k))
        if root ** k == number:
            return k
    return 1



