import re

def text_match_two_three(text: str, pattern: str) -> bool:
    count = 0
    i = 0
    while i <= len(text):
        match = re.search(pattern, text[i:])
        if not match:
            break
        start = i + match.start()
        # Move index forward by 1 to allow overlapping matches
        i = start + 1
        count += 1
        if count > 3:
            return False
    return 2 <= count <= 3



