def remove_column(data, key=None, index=None):
    if key is not None and index is None:
        def remove_key(obj):
            if isinstance(obj, dict):
                return {k: remove_key(v) for k, v in obj.items() if k != key}
            elif isinstance(obj, list):
                return [remove_key(item) for item in obj]
            else:
                return obj
        return remove_key(data)
    elif index is not None and key is None:
        for inner in data:
            if isinstance(inner, list) and len(inner) > index:
                del inner[index]
        return data
    else:
        # Behavior undefined when both or neither are provided; just return data as is.
        return data



