def lucky_num(n):
    if n == 0:
        return []
    nums = list(range(1, 10 * n * n))  # oversize initial list to be safe
    lucky_nums = []
    idx = 0
    while len(lucky_nums) < n:
        if idx >= len(nums):
            # extend nums if needed (should rarely happen with oversize)
            last = nums[-1]
            nums.extend(range(last + 1, last + 10 * n * n))
        lucky = nums[idx]
        lucky_nums.append(lucky)
        step = lucky
        if step <= 1:
            idx += 1
            continue
        # Remove every step-th element from nums, counting from 1-based indexing
        # i.e. remove elements at indices step-1, 2*step-1, 3*step-1, ...
        # but be careful to count after each removal
        filtered = []
        count = 0
        for num in nums:
            count += 1
            if count % step != 0:
                filtered.append(num)
        nums = filtered
        idx += 1
    return lucky_nums



