def compute_Last_Digit(a: int, b: int) -> int:
    if a > b:
        return 0
    if a == b:
        return 1

    # The quotient is product of integers from a+1 to b
    # We want the last non-zero digit of this product.

    # Count total number of 2s and 5s in factorization to remove trailing zeros
    def count_factor(n, f):
        count = 0
        while n % f == 0 and n > 0:
            n //= f
            count += 1
        return count

    total_twos = 0
    total_fives = 0
    digits = 1

    for x in range(a + 1, b + 1):
        n = x
        twos = 0
        fives = 0
        while n % 2 == 0 and n > 0:
            n //= 2
            twos += 1
        while n % 5 == 0 and n > 0:
            n //= 5
            fives += 1
        total_twos += twos
        total_fives += fives
        digits = (digits * n) % 10

    # Remove pairs of (2,5) to remove trailing zeros
    diff = total_twos - total_fives
    # Multiply digits by 2^(diff) mod 10 to add leftover 2s
    # Only leftover 2s remain after removing pairs with 5s
    for _ in range(diff):
        digits = (digits * 2) % 10

    # digits now holds last non-zero digit of quotient
    return digits



