def next_smallest_palindrome(n: int) -> int:
    """
    Given a positive integer n, return the largest palindrome number that is strictly less than n.

    A palindrome number is a number that reads the same forwards and backwards.

    Parameters:
    n (int): A positive integer.

    Returns:
    int: The largest palindrome number smaller than n.
    """
    if n <= 1:
        return 0  # For n=1, largest palindrome less than 1 is 0

    s = str(n)
    length = len(s)

    # Handle special case: all digits are '0' or '1' and n is very small (e.g. 1 already handled)
    # No need for that as n >= 1 is input, and we handle n=1 above.

    # Helper to build palindrome from left half and middle (if odd length)
    def build_palindrome(left: str, middle: str, odd: bool) -> int:
        if odd:
            return int(left + middle + left[::-1])
        else:
            return int(left + left[::-1])

    # If n is single digit, just return n-1 (single digit palindrome)
    if length == 1:
        return n - 1

    odd = (length % 2 != 0)
    mid_index = length // 2

    left = s[:mid_index]
    middle = s[mid_index] if odd else ''

    # Construct palindrome by mirroring left + middle
    pal = build_palindrome(left, middle, odd)

    if pal < n:
        return pal

    # If palindrome >= n, we need to decrement the palindrome

    # Convert to list for manipulation
    if odd:
        left_middle = left + middle
    else:
        left_middle = left

    # Convert to int
    left_middle_num = int(left_middle)

    # Decrement left_middle_num by 1
    left_middle_num -= 1

    # If after decrement left_middle_num is negative, means we have to consider smaller length palindrome
    if left_middle_num < 0:
        # e.g. n=1000, try palindrome of length-1 digits all 9
        return int('9' * (length - 1))

    left_middle_str = str(left_middle_num)

    # Pad with zeros if needed (when decrementing reduces length)
    if len(left_middle_str) < len(left_middle):
        left_middle_str = '0' * (len(left_middle) - len(left_middle_str)) + left_middle_str

    if odd:
        left_new = left_middle_str[:-1]
        middle_new = left_middle_str[-1]
        pal = build_palindrome(left_new, middle_new, odd)
    else:
        left_new = left_middle_str
        pal = build_palindrome(left_new, '', odd)

    # If palindrome is zero or negative, return largest palindrome with smaller length
    if pal <= 0:
        return int('9' * (length - 1))

    return pal



