def get_total_number_of_sequences(max_value: int, max_length: int) -> int:
    if max_length < 1 or max_value < 1:
        return 0
    # dp[length][value] = number of sequences of length 'length' ending with 'value'
    dp = [ [0]*(max_value+1) for _ in range(max_length+1) ]
    # For length=1, each value 1..max_value forms one sequence
    for v in range(1, max_value+1):
        dp[1][v] = 1
    for length in range(2, max_length+1):
        # To optimize, precompute prefix sums for dp[length-1]
        prefix_sums = [0]*(max_value+2)
        for val in range(1, max_value+1):
            prefix_sums[val] = prefix_sums[val-1] + dp[length-1][val]
        for val in range(1, max_value+1):
            min_prev = (val + 1) // 2  # previous element <= val/2 implies val >= 2*prev
            # sum dp[length-1][prev] for prev in [1..floor(val/2)]
            dp[length][val] = prefix_sums[val//2]
    total = 0
    for length in range(1, max_length+1):
        total += sum(dp[length][1:])
    return total



