def remove_column(collection, position):
    outer_type = type(collection)
    result = []
    for inner in collection:
        inner_type = type(inner)
        length = len(inner)
        # Normalize negative index
        idx = position if position >= 0 else length + position
        if 0 <= idx < length:
            # Remove element at idx
            new_inner = inner[:idx] + inner[idx+1:]
            # Convert back to original type
            if inner_type is tuple:
                new_inner = tuple(new_inner)
            elif inner_type is list:
                new_inner = list(new_inner)
            else:
                try:
                    new_inner = inner_type(new_inner)
                except Exception:
                    new_inner = list(new_inner)
            result.append(new_inner)
        else:
            # Position out of range, keep inner unchanged
            result.append(inner)
    # Convert outer to original type
    if outer_type is tuple:
        return tuple(result)
    elif outer_type is list:
        return list(result)
    else:
        try:
            return outer_type(result)
        except Exception:
            return list(result)



