from collections import Counter

def permute_string(text):
    if text == '':
        return ['']
    counts = Counter(text)
    result = []
    def backtrack(path, counter):
        if len(path) == len(text):
            result.append(''.join(path))
            return
        for ch in counter:
            if counter[ch] > 0:
                counter[ch] -= 1
                path.append(ch)
                backtrack(path, counter)
                path.pop()
                counter[ch] += 1
    backtrack([], counts)
    return result



