def multi_list(data: list) -> list:
    n = len(data)
    if n == 0:
        return [[]]
    if n == 1:
        return [data[:]]
    # Find all factor pairs (rows, cols) with rows > 1 and rows * cols == n
    factor_pairs = []
    for r in range(2, n + 1):
        if n % r == 0:
            c = n // r
            factor_pairs.append((r, c))
    # If no factor pairs with rows > 1 found, length is prime > 1
    if not factor_pairs:
        return [data[:]]
    # Choose factor pair with smallest rows > 1
    rows, cols = min(factor_pairs, key=lambda x: x[0])
    return [data[i * cols:(i + 1) * cols] for i in range(rows)]



