def find_Max(sequence):
    """
    Given a sequence of integers that is a rotated sorted sequence—originally sorted in strictly increasing order and then rotated—return the greatest entry in the sequence.

    Parameters:
    sequence (list of int): A rotated sorted sequence of integers, originally sorted in strictly increasing order.

    Returns:
    int: The maximum element in the sequence.
    """
    left, right = 0, len(sequence) - 1
    # If the sequence is not rotated (last element > first element), max is at the end
    if sequence[left] < sequence[right]:
        return sequence[right]

    while left < right:
        mid = (left + right) // 2
        if sequence[mid] > sequence[right]:
            # Max is in the right part, including mid
            left = mid + 1
        else:
            # Max is in the left part, excluding mid
            right = mid
    # After loop, left == right points to the smallest element
    # Max is element before smallest, handling wrap-around
    return sequence[left - 1 if left > 0 else len(sequence) - 1]



