from math import prod

def sum_Of_product(*args):
    if all(not (isinstance(arg, Iterable) and not isinstance(arg, (str, bytes))) for arg in args):
        # All arguments are single numbers, multiply all together and return
        result = 1
        for arg in args:
            result *= arg
        return result
    else:
        # For each argument: if iterable, product of elements; else the number; sum all
        total = 0
        for arg in args:
            if isinstance(arg, Iterable) and not isinstance(arg, (str, bytes)):
                total += prod(arg)
            else:
                total += arg
