def str_to_tuple(s: str) -> tuple[int, ...]:
    if not s:
        raise ValueError("Input string is empty")
    # Identify delimiter by scanning non-digit characters (assumes consistent delimiter)
    delimiters = set(c for c in s if not c.isdigit())
    if not delimiters:
        # No delimiter, single group
        if s.startswith('-'):
            raise ValueError("Negative numbers not supported")
        return (int(s),)
    if len(delimiters) > 1:
        # Multiple different delimiters found, ambiguous input
        raise ValueError("Multiple different delimiters found")
    delim = delimiters.pop()
    # Split by delimiter
    parts = s.split(delim)
    if any(not part for part in parts):
        raise ValueError("Empty group found due to consecutive delimiters or leading/trailing delimiter")
    result = []
    for part in parts:
        if part.startswith('-'):
            raise ValueError("Negative numbers not supported")
        if not part.isdigit():
            raise ValueError("Groups must be digits only")
        result.append(int(part))
    return tuple(result)



