import re

def capital_words_spaces(text: str) -> str:
    # Preserve original leading spaces
    leading_spaces_match = re.match(r'^[ \t]*', text)
    leading_spaces = leading_spaces_match.group(0) if leading_spaces_match else ''
    rest = text[len(leading_spaces):]

    # Insert space before capital letters that are immediately preceded by a non-space, non-capital letter
    # This splits camelCase or concatenated capitalized words, punctuation or lowercase followed by uppercase
    rest = re.sub(r'(?<=[^ \tA-Z])([A-Z])', r' \1', rest)

    # Replace multiple spaces before capital letters with a single space
    # (including cases where multiple spaces existed originally)
    rest = re.sub(r' +([A-Z])', r' \1', rest)

    # Combine preserved leading spaces with processed rest
    return leading_spaces + rest



