def length_Of_Last_Word(s: str, n: int) -> int:
    if n == 0:
        return 0
    sub = s[-n:]
    i = len(sub) - 1
    # Skip trailing spaces
    while i >= 0 and sub[i] == ' ':
        i -= 1
    if i < 0:
        return 0
    end = i
    # Find start of last word in substring
    while i >= 0 and sub[i] != ' ':
        i -= 1
    start = i + 1
    last_word_sub = sub[start:end + 1]
    # Find full last word in original string including partial
    # Determine original start index of last_word_sub in s
    sub_start_in_s = len(s) - n + start
    # Move left in s while characters are non-space to find full word start
    word_start = sub_start_in_s
    while word_start > 0 and s[word_start - 1] != ' ':
        word_start -= 1
    # Move right in s while characters are non-space to find full word end
    word_end = sub_start_in_s + len(last_word_sub)
    while word_end < len(s) and s[word_end] != ' ':
        word_end += 1
    return word_end - word_start



