def dif_Square(n: int) -> bool:
    from math import isqrt

    # n = a^2 - b^2 = (a-b)(a+b), with a,b >= 0 integers
    # Let x = a-b >= 0 and y = a+b >= x
    # Then n = x * y, with y >= x >= 0, and a = (x+y)/2, b = (y-x)/2 integers >= 0
    # So (x+y) and (y-x) must be even (to make a,b integers)
    # Also, a,b >= 0 => (x+y) >= (y-x) >= 0, which is true if y >= x >= 0

    if n == 0:
        # 0 = 0^2 - 0^2 trivially
        return True

    # For negative n, check if difference of squares possible with a,b >=0
    # Since n = a^2 - b^2 = (a-b)(a+b), if n < 0, then a < b
    # Let m = -n > 0, then m = b^2 - a^2
    # The same logic applies: check if m can be represented as difference of squares with nonnegative integers
    # So the problem reduces to checking n >= 0 or -n >= 0

    target = abs(n)
    limit = isqrt(target)

    for x in range(1, limit + 1):
        if target % x == 0:
            y = target // x
            if y >= x:
                # Check parity conditions for a,b integer
                if (x + y) % 2 == 0 and (y - x) % 2 == 0:
                    a = (x + y) // 2
                    b = (y - x) // 2
                    if a >= 0 and b >= 0:
                        # For n >= 0, a^2 - b^2 = n
                        # For n < 0, b^2 - a^2 = -n => a,b swapped roles
                        if n >= 0:
                            if a >= b:
                                return True
                        else:
                            if b >= a:
                                return True
