def next_smallest_palindrome(num: int) -> int:
    def is_palindrome(x: int) -> bool:
        s = str(x)
        return s == s[::-1]

    if num <= 1:
        # Only palindrome smaller than 1 is 0 (allowed per test_3)
        return 0

    s = str(num)
    length = len(s)
    odd = (length % 2 != 0)
    half_len = (length + 1) // 2

    def make_palindrome(left: str, odd: bool) -> int:
        if odd:
            return int(left + left[-2::-1])
        else:
            return int(left + left[::-1])

    left = s[:half_len]
    pal = make_palindrome(left, odd)

    if pal >= num:
        # Decrement the left half as integer
        left_num = int(left) - 1
        # If decrement leads to zero or negative, fallback to largest palindrome with fewer digits
        if left_num <= 0:
            # e.g. num=10 -> return 9, num=100 -> return 99, etc.
            return int('9' * (length - 1)) if length > 1 else 0
        left = str(left_num).rjust(half_len, '0')
        pal = make_palindrome(left, odd)

    # If palindrome still >= num (can happen if decrement doesn't reduce palindrome enough),
    # or palindrome < 0 (should not happen), fallback to largest palindrome with fewer digits
    if pal >= num or pal < 0:
        if length == 1:
            # single digit numbers: return one less
            return num - 1
        return int('9' * (length - 1))

    # Sometimes pal might start with zeros after decrement, fix by removing leading zeros and re-mirroring
    # e.g. left='099' -> '099' palindrome may be invalid if leading zero
    # So if left starts with '0', fallback to smaller length palindrome
    if left[0] == '0':
        if length == 1:
            return num - 1
        return int('9' * (length - 1))

    return pal



