def get_total_number_of_sequences(n: int, m: int) -> int:
    if n == 1:
        return m
    dp = [0] * (m + 1)
    for x in range(1, m + 1):
        dp[x] = 1
    for length in range(2, n + 1):
        new_dp = [0] * (m + 1)
        for prev in range(1, m + 1):
            count = dp[prev]
            if count == 0:
                continue
            start = 2 * prev
            if start > m:
                continue
            for curr in range(start, m + 1):
                new_dp[curr] += count
        dp = new_dp
    return sum(dp[1 : m + 1])



