def drop_empty(d):
    """
    Return a new dictionary based on the input dictionary `d` where all items with values that are empty containers
    (such as empty strings "", empty lists [], empty dictionaries {}), or None are removed. Values that are falsy
    but not empty containers or None (such as 0 or False) should be retained.

    The original dictionary should not be modified.

    Examples:
    >>> drop_empty({'a': 0, 'b': '', 'c': 1})
    {'a': 0, 'c': 1}
    >>> drop_empty({'x': [], 'y': None, 'z': [1, 2]})
    {'z': [1, 2]}
    >>> drop_empty({'foo': {}, 'bar': False, 'baz': 'text'})
    {'bar': False, 'baz': 'text'}
