def find_Max(arr):
    """
    Given a sorted and rotated array of distinct integers, return the maximum element in the array.

    The input array is originally sorted in ascending order and then rotated at some pivot unknown to you beforehand.
    Your task is to find and return the maximum element itself.

    Examples:
    find_Max([4,5,6,7,0,1,2]) -> 7
    find_Max([6,7,0,1,2,4,5]) -> 7
    find_Max([1,2,3,4,5]) -> 5
    find_Max([2,3,4,5,1]) -> 5
    """
    low, high = 0, len(arr) - 1
    while low < high:
        mid = (low + high) // 2
        if arr[mid] > arr[high]:
            low = mid + 1
        else:
            high = mid
    # low is index of minimum element
    # maximum is element before minimum; handle wrap around
    return arr[low - 1] if low > 0 else arr[-1]



