def lucky_num(n):
    if n == 0:
        return []
    numbers = list(range(1, 2 * n * n))  # heuristic upper bound to ensure enough lucky numbers
    idx = 1
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        del numbers[step - 1::step]
        idx += 1
        if len(numbers) >= n:
            continue
        # If too few numbers remain, extend the list
        last = numbers[-1]
        extension = list(range(last + 1, last + n * 2))
        numbers.extend(extension)
    return numbers[:n]



